const v=page.evaluate((x,y)=>{const f=(id,n)=>[...document.querySelectorAll("#"+id+" option")].find(o=>o.textContent.startsWith(n));return [f("p1",x)?.value,f("p2",y)?.value]},x,y);
out.push(v);
if(v[0]&&v[1]){page.goto("https://www.timeanddate.com/worldclock/distanceresult.html?p1="+v[0]+"&p2="+v[1]);
out.push(page.evaluate(()=>document.body.innerText.match(/Distance from[^\n]*\n[^\n]*/)[0]));}
}
return out;
